from pathlib import Path

def write_pybind_file(headers, module, bindings, output):

    lines = [
        "// Autogenerated file",
        "// Copyright (c) 2026 Mike Kipnis — QuantLibAddIn/Python",
        "#include <pybind11/pybind11.h>",
        "#include <pybind11/stl.h>",
        "#include <oh/property.hpp>",
        "#include <string>",
        "#include <vector>",
        "#include <ql/time/date.hpp>",
        "#include <oh/repository.hpp>",
        "#include <addincpp.hpp>",
    ]

    for header in headers:
        lines.append(f'#include <{Path(header).name}>')

    lines.append('#include <qlap.hpp>')

    qlAddinCalculate = r'''  m.def( 
        "qlAddinCalculate",
            [](const std::string& ObjectId, const py::dict& input) -> py::dict {
            const json::value json_input = qlap::to_boost_json(input);
            const json::value json_output =
                qlap::qlAddinCalculate(ObjectId, json_input);

            return qlap::to_python_dict(json_output);
        },
        py::arg("ObjectId"),
        py::arg("input") = py::dict(),
        "Calculate using a Python dictionary and return a dictionary."
        );'''

    ohPropertyFromPython = r'''
    py::class_<ObjectHandler::property_t>(m, "Property")
    .def(py::init<>())
    .def(py::init([](const py::object& value) {
        return QuantLibAddinPython::property_from_python(value);
    }));
    '''

    lines.extend([
        "",
        "namespace py = pybind11;",
        "namespace qlap = QuantLibAddinPython;",
        "",
        f"PYBIND11_MODULE({module}, m)",
        "{",
        qlAddinCalculate,
        ohPropertyFromPython,
        "",
    ])

    for binding in bindings:
        lines.extend([binding, ""])

    lines.extend(["}", ""])

    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text("\n".join(lines), encoding="utf-8")
